def salin_alamat_profil(apps, schema_editor):
    """Pindahkan alamat tunggal di Profile (versi sebelumnya) menjadi alamat utama di tabel Alamat."""
    Profile = apps.get_model('laundry', 'Profile')
    Alamat = apps.get_model('laundry', 'Alamat')
    for p in Profile.objects.exclude(alamat_lengkap='').select_related('user'):
        if Alamat.objects.filter(user_id=p.user_id).exists():
            continue
        u = p.user
        Alamat.objects.create(
            user_id=p.user_id,
            label=p.alamat_label or 'Rumah',
            nama_penerima=(f'{u.first_name} {u.last_name}').strip() or u.email.split('@')[0] or u.username,
            whatsapp=p.whatsapp,
            alamat_lengkap=p.alamat_lengkap[:255],
            kota='Samarinda',
            catatan_kurir=p.alamat_catatan,
            utama=True,
        )


